import ast,json,hashlib
from pathlib import Path
p=json.loads(Path('/workspace/proposal.json').read_text())
sources={v['name']:Path('/workspace/'+v['file']).read_text() for v in p['variants']}
for n,s in sources.items(): compile(s,n+'.py','exec')
trees={n:ast.parse(s) for n,s in sources.items()}
def without_config(t):
 return ast.dump(ast.Module(body=[n for n in t.body if not (isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))],type_ignores=[]),include_attributes=False)
assert len(set(map(without_config,trees.values())))==1
parent=ast.parse(Path('/workspace/history_r0034_closure_half.py').read_text())
def methods(t):
 m=next(x for x in t.body if isinstance(x,ast.ClassDef) and x.name=='Model')
 return {x.name:ast.dump(x,include_attributes=False) for x in m.body if isinstance(x,(ast.FunctionDef,ast.AsyncFunctionDef))}
a=methods(parent);b=methods(trees['rank_reflection'])
changed=[k for k in a if k in b and a[k]"'!=b[k]]
assert set(changed)=={'"'__init__','_rotation_donors','_event_scales','diagnostics'}, changed
for name in ('_encode','_weights','_logits','_normalize_product','_scores_from_product','_product','forward','training_loss'):
 assert a[name]==b[name],name
for v in p['variants']:
 t=trees[v['name']]
 cfg=ast.literal_eval(next(n.value for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets)))
 assert cfg==v['config']
 for n in ast.walk(t):
  if isinstance(n,ast.Import): assert all(x.name.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'} for x in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','__import__','compile'}
 print(v['file'],'syntax OK','source_sha256',hashlib.sha256(sources[v['name']].encode()).hexdigest())
print('CONFIG-only pair equivalence: PASS')
print('Parent changed methods:',changed,'removed:',set(a)-set(b),'added:',set(b)-set(a))
print('Active normalization/forward/BCE source preservation: PASS')
PY"

