 if 'const' in sch: assert x==sch['const'],(path,'const')
 if 'enum' in sch: assert x in sch['enum'],(path,'enum')
 if 'minLength' in sch: assert len(x)>=sch['minLength'],path
 if 'minItems' in sch: assert len(x)>=sch['minItems'],path
 if isinstance(x,dict):
  assert all(k in x for k in sch.get('required',[])),(path,'required')
